export async function loadPlain({ repo, meta, head: headCommit, token, gh = defaultGh, now = Date.now(), kind = 'plain', error = null, onError, readCatalog = readPackCatalog }) {
  const [offer, runs, activity] = await Promise.all([
    readOffer({ repo, sha: headCommit?.sha, token, gh, readCatalog }),
    gh.listRuns(repo, token).catch((e) => { onError?.(`Actions unreadable — ${e.message}`); return []; }),
    gh.commitActivity(repo, token).catch(() => null),
  ]);
  renderBanner(repo, kind, error);
  renderOffer(offer);
  renderFacts(meta, headCommit, now);
  renderCi(defaultBranchCi(runs, meta.default_branch), meta.default_branch, now);
  renderCommits(commitWeeks(activity, COMMIT_WEEKS));
  renderRuns(runsByHour(runs, now, { hours: RUN_HOURS, pageFull: runs.length >= (gh.RUNS_PER_PAGE ?? Infinity) }));
  return { branch: meta.default_branch, sha: headCommit?.sha ?? '', runs: runs.length };
}

